#include <stdio.h>

int main(void) {
    long lines = 0, words = 0, bytes = 0, maxlen = 0;
    int in_word = 0;
    int c;
    unsigned long cur_line_len = 0;
    /* is_w: whitespace exactly space \t \n \v \f \r */
    #define IS_W(b) ((b) == ' ' || (b) == '\t' || (b) == '\n' || (b) == '\v' || (b) == '\f' || (b) == '\r')

    while ((c = getchar()) != EOF) {
        bytes++;
        if (c == '\n') {
            lines++;
            if (cur_line_len > maxlen)
                maxlen = cur_line_len;
            cur_line_len = 0;
        } else {
            cur_line_len++;
        }

        if (IS_W(c)) {
            in_word = 0;
        } else if (!in_word) {
            words++;
            in_word = 1;
        }
    }
    /* A last line without trailing newline counts as a line */
    if (bytes > 0 && cur_line_len > 0) {
        lines++;
        if (cur_line_len > maxlen)
            maxlen = cur_line_len;
    }

    printf("%ld %ld %ld %lu\n", lines, words, bytes, maxlen);
    return 0;
}

